(* [comment removed for export] *)
Definition icells (m : mem) : Prop :=
  ro_cells asegs m 0x225d20 [C8 (Z_to_bv 64 0x244ab8)]            (* [comment removed for export] *)
  /\ ro_cells asegs m 0x2268a0 [C8 (Z_to_bv 64 0x245799)]         (* [comment removed for export] *)
  /\ ro_cells asegs m 0x227e90 [C8 (Z_to_bv 64 0x217f04)]         (* [comment removed for export] *)
  /\ ro_cells asegs m 0x244ab8 [C8 (Z_to_bv 64 0x7fff8000)]      (* [comment removed for export] *)
